// Rumbo 2 — personal goals and a local, manually maintained resale ledger.
Object.assign(PATHS,{target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 10v4m-2-2h4',shop:'M3 8l2-5h14l2 5v3a3 3 0 0 1-6 0 3 3 0 0 1-6 0 3 3 0 0 1-6 0V8m2 6v7h14v-7M9 21v-5h6v5',box:'M3 7l9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',money:'M3 5h18v14H3zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M6 9v6m12-6v6'});
Object.assign(ui,{goalFilter:'active',businessTab:'overview',salesMonth:'all',productSearch:'',showArchivedProducts:false,productTrash:false});
const CURRENCIES={PEN:'Soles peruanos (PEN)',USD:'Dólares (USD)',MXN:'Pesos mexicanos (MXN)',COP:'Pesos colombianos (COP)',EUR:'Euros (EUR)'};
const GOAL_CATEGORIES={personal:'Personal',estudio:'Aprendizaje',ahorro:'Ahorro',negocio:'Negocio',bienestar:'Bienestar'};
let ledgerCache=null;
function invalidateLedger(){ledgerCache=null;}
function ledger(){
 if(ledgerCache&&ledgerCache.owner===state.business&&ledgerCache.date===today())return ledgerCache;
 const used=new Map(),usedToday=new Map(),stocks=new Map();const blank=()=>({quantity:0,cost:0,averageCost:0,pending:0,invested:0,totalReceivedCost:0,receivedUnits:0});
 for(const s of state.business.sales){if(s.voided)continue;for(const a of s.allocations){if(!used.has(a.purchaseId))used.set(a.purchaseId,[]);used.get(a.purchaseId).push(a);if(s.date<=today()){if(!usedToday.has(a.purchaseId))usedToday.set(a.purchaseId,[]);usedToday.get(a.purchaseId).push(a);}}}
 for(const arr of used.values())arr.sort((a,b)=>a.start-b.start);
 for(const p of state.business.purchases){if(p.voided||p.date>today())continue;if(!stocks.has(p.productId))stocks.set(p.productId,blank());const st=stocks.get(p.productId);st.invested+=purchaseTotal(p);if(p.status==='pending'||p.receivedDate>today()){st.pending+=p.quantity;continue;}const allocations=usedToday.get(p.id)||[];st.quantity+=p.quantity-allocations.reduce((n,a)=>n+a.quantity,0);st.cost+=purchaseTotal(p)-allocations.reduce((n,a)=>n+a.cost,0);st.totalReceivedCost+=purchaseTotal(p);st.receivedUnits+=p.quantity;}
 for(const s of stocks.values())s.averageCost=s.quantity?Math.round(s.cost/s.quantity):0;
 ledgerCache={owner:state.business,date:today(),used,usedToday,stocks,blank};return ledgerCache;
}
function defaultBusiness(){return {currency:'PEN',products:[],purchases:[],sales:[],expenses:[],profitAllocation:defaultProfitAllocation()};}
function topAction(){if(ui.view==='goals')return `<button class="btn" data-action="goal-new">${icon('plus',16)}Nueva meta</button>`;if(ui.view==='business')return `<button class="btn" data-action="sale-new" ${!state.business.products.some(p=>!p.deleted&&!p.archived&&stockInfo(p.id).quantity>0)?'disabled title="Primero registra productos y existencias recibidas"':''}>${icon('plus',16)}Registrar venta</button>`;return `<button class="btn" data-action="event-new">${icon('plus',16)}Nuevo bloque</button>`;}
function renderMobileNav(){const tabs=[['today','home','Hoy'],['schedule','calendar','Horario'],['habits','habits','Hábitos'],['goals','target','Metas'],['business','shop','Ventas']];return `<nav class="mobile-nav" aria-label="Navegación móvil">${tabs.map(([v,i,n])=>`<button data-action="view" data-view="${v}" class="${ui.view===v?'active':''}" ${ui.view===v?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}<button data-action="more-nav" class="${['progress','routes','settings'].includes(ui.view)?'active':''}" aria-label="Más apartados">${icon('more')}Más</button></nav>`;}
function habitDateNotice(){if(ui.date>today())return `<div class="banner date-banner" role="status">${icon('calendar')}<div><strong>Estás viendo una fecha futura: ${fmtDate(ui.date)}.</strong><br>Hoy es ${fmtDate(today())}. Los hábitos se marcan el día que los cumples.</div><button class="btn soft small" data-action="habit-go-today">Volver a hoy</button></div>`;if(ui.date<today())return `<p class="muted-note">${icon('back',14)}Estás revisando el ${fmtDate(ui.date)}. Puedes corregir las marcas de esa fecha o volver a hoy.</p>`;return `<p class="muted-note">${icon('check',14)}Marca lo que cumpliste hoy. El cambio se guarda automáticamente.</p>`;}
function habitCompleteButton(h,due,done){if(ui.date>today())return `<button class="btn soft small" data-action="habit-go-today">Marcar hoy</button>`;if(!due)return '<span>No previsto este día</span>';return `<button class="habit-complete ${done?'done':''}" data-action="habit-toggle" data-id="${h.id}" data-date="${ui.date}" aria-pressed="${done}" aria-label="${done?'Desmarcar':'Cumplí'} ${esc(h.name)}">${icon('check',15)}${done?'Cumplido':'Marcar como hecho'}</button>`;}
function money(cents){return new Intl.NumberFormat('es-PE',{style:'currency',currency:state?.business?.currency||'PEN',currencyDisplay:'narrowSymbol',minimumFractionDigits:2}).format(cents/100);}
function amount(cents){return (cents/100).toFixed(2);}
function readCents(value,label='El importe'){const s=String(value).trim().replace(',','.');if(!/^\d{1,10}(?:\.\d{1,2})?$/.test(s))throw Error(`${label} debe ser un importe positivo o cero, con hasta dos decimales.`);const [a,b='']=s.split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>1e12)throw Error(`${label} es demasiado grande.`);return n;}
function readQuantity(value,min=1){const s=String(value);const n=Number(s);if(!/^\d+$/.test(s)||!Number.isSafeInteger(n)||n<min||n>1000000)throw Error(`La cantidad debe ser un entero entre ${min} y 1.000.000.`);return n;}
function purchaseTotal(p){return p.quantity*p.unitCost+p.extraCost;}
function saleTotal(s){return s.quantity*s.unitPrice-s.discount;}
function saleCOGS(s){return s.allocations.reduce((n,a)=>n+a.cost,0);}
function activeSales(asOf=today()){return state.business.sales.filter(s=>!s.voided&&s.date<=asOf);}
function batchCost(p,start,quantity){const total=BigInt(purchaseTotal(p)),q=BigInt(p.quantity);return Number(total*BigInt(start+quantity)/q-total*BigInt(start)/q);}
function batchUsed(purchaseId,asOf=null){const index=ledger();if(!asOf)return index.used.get(purchaseId)||[];if(asOf===today())return index.usedToday.get(purchaseId)||[];return state.business.sales.filter(s=>!s.voided&&s.date<=asOf).flatMap(s=>s.allocations.filter(a=>a.purchaseId===purchaseId)).sort((a,b)=>a.start-b.start);}
function freeRanges(p){const ranges=[];let from=0;for(const a of batchUsed(p.id)){if(a.start>from)ranges.push({start:from,quantity:a.start-from});from=Math.max(from,a.start+a.quantity);}if(from<p.quantity)ranges.push({start:from,quantity:p.quantity-from});return ranges;}
function allocateSale(productId,quantity,date=today()){let remaining=quantity;const result=[];const batches=state.business.purchases.filter(p=>p.productId===productId&&!p.voided&&p.status==='received'&&(p.receivedDate||p.date)<=date).sort((a,b)=>(a.receivedDate||a.date).localeCompare(b.receivedDate||b.date)||a.date.localeCompare(b.date));for(const p of batches){for(const r of freeRanges(p)){if(!remaining)break;const take=Math.min(r.quantity,remaining);result.push({purchaseId:p.id,start:r.start,quantity:take,cost:batchCost(p,r.start,take)});remaining-=take;}if(!remaining)break;}if(remaining)throw Error('No hay suficientes unidades recibidas y disponibles para esa fecha. Revisa las existencias o recibe primero el pedido.');return result;}
function stockInfo(productId){const index=ledger();return index.stocks.get(productId)||index.blank();}
function salesStats(){const b=state.business,ps=b.purchases.filter(p=>!p.voided&&p.date<=today()),sales=activeSales();const revenue=sales.reduce((n,s)=>n+saleTotal(s),0),cogs=sales.reduce((n,s)=>n+saleCOGS(s),0),fees=sales.reduce((n,s)=>n+s.fees,0),collected=sales.reduce((n,s)=>n+s.payments.filter(p=>p.date<=today()).reduce((v,p)=>v+p.amount,0),0),expenses=b.expenses.filter(e=>!e.voided&&e.date<=today()).reduce((n,e)=>n+e.amount,0),invested=ps.reduce((n,p)=>n+purchaseTotal(p),0);const stocks=b.products.map(p=>stockInfo(p.id));return {revenue,cogs,fees,collected,expenses,invested,netProfit:revenue-cogs-fees-expenses,cashBalance:collected-invested-fees-expenses,receivable:revenue-collected,capitalRemaining:Math.max(0,invested+fees+expenses-collected),inventoryCost:stocks.reduce((n,s)=>n+s.cost,0),inventoryQuantity:stocks.reduce((n,s)=>n+s.quantity,0),receivedCost:stocks.reduce((n,s)=>n+s.totalReceivedCost,0),receivedUnits:stocks.reduce((n,s)=>n+s.receivedUnits,0),soldUnits:sales.reduce((n,s)=>n+s.quantity,0),pendingUnits:stocks.reduce((n,s)=>n+s.pending,0)};}

function validateExtensions(raw){
 if(raw.schemaVersion===1)return {goals:[],business:defaultBusiness(),learning:validateLearning(raw.learning)};
 const fail=msg=>{throw Error(msg);},text=(v,n=1000)=>typeof v==='string'&&v.length<=n,uid=v=>text(v,100)&&/^[a-zA-Z0-9_-]+$/.test(v)&&!['__proto__','constructor','prototype'].includes(v),integer=(n,min=0,max=1e12)=>Number.isSafeInteger(n)&&n>=min&&n<=max;
 const list=(a,max)=>Array.isArray(a)&&a.length<=max&&new Set(a.map(v=>v.id)).size===a.length;
 if(!list(raw.goals,1000))fail('Las metas de la copia no son válidas.');
 for(const g of raw.goals){if(!uid(g.id)||!text(g.title,120)||!g.title.trim()||!text(g.notes,2000)||!GOAL_CATEGORIES[g.category]||!['number','checklist','business'].includes(g.mode)||!Number.isFinite(g.target)||g.target<=0||g.target>1e12||!Number.isFinite(g.current)||g.current<0||g.current>1e12||!text(g.unit,30)||(g.deadline&&!validDate(g.deadline))||!list(g.steps,200)||typeof g.archived!=='boolean')fail('Hay una meta no válida.');for(const s of g.steps)if(!uid(s.id)||!text(s.title,160)||typeof s.done!=='boolean')fail('Un paso de una meta no es válido.');}
 const b=raw.business;if(!b||!CURRENCIES[b.currency]||!list(b.products,10000)||!list(b.purchases,100000)||!list(b.sales,100000)||!list(b.expenses,100000))fail('Los datos de ventas no son válidos.');
 const products=new Map(),purchases=new Map(),occupied=new Map();
 for(const p of b.products){if(!uid(p.id)||!text(p.name,120)||!p.name.trim()||!integer(p.price)||!integer(p.lowStock,0,1000000)||!text(p.notes)||typeof p.archived!=='boolean')fail('Hay un producto no válido.');products.set(p.id,p);}
 for(const p of b.purchases){if(!uid(p.id)||!products.has(p.productId)||!integer(p.quantity,1,1000000)||!integer(p.unitCost)||!integer(p.extraCost)||!integer(purchaseTotal(p))||!validDate(p.date)||!['pending','received'].includes(p.status)||(p.status==='received'&&!validDate(p.receivedDate))||(p.expectedDate&&!validDate(p.expectedDate))||!text(p.notes)||typeof p.voided!=='boolean')fail('Hay una compra no válida.');purchases.set(p.id,p);}
 for(const s of b.sales){if(!uid(s.id)||!products.has(s.productId)||!integer(s.quantity,1,1000000)||!integer(s.unitPrice)||!integer(s.discount)||!integer(s.fees)||!integer(saleTotal(s))||!validDate(s.date)||!text(s.customer,120)||!text(s.notes)||typeof s.voided!=='boolean'||!Array.isArray(s.allocations)||s.allocations.length>10000||!list(s.payments,1000))fail('Hay una venta no válida.');let qty=0;for(const a of s.allocations){const p=purchases.get(a.purchaseId);if(!p||p.productId!==s.productId||!integer(a.start,0,1000000)||!integer(a.quantity,1,1000000)||a.start+a.quantity>p.quantity||!integer(a.cost)||a.cost!==batchCost(p,a.start,a.quantity)||(!s.voided&&(p.voided||p.status!=='received'||p.receivedDate>s.date)))fail('El costo o las existencias de una venta no coinciden con sus compras.');qty+=a.quantity;if(!s.voided){const used=occupied.get(p.id)||[];used.push(a);occupied.set(p.id,used);}}if(qty!==s.quantity)fail('La cantidad vendida no coincide con el inventario asignado.');let paid=0;for(const pay of s.payments){if(!uid(pay.id)||!integer(pay.amount,1)||!validDate(pay.date)||pay.date<s.date)fail('Hay un cobro no válido.');paid+=pay.amount;}if(paid>saleTotal(s))fail('Una venta tiene más cobros que su total.');}
 for(const used of occupied.values()){used.sort((a,b)=>a.start-b.start);for(let i=1;i<used.length;i++)if(used[i].start<used[i-1].start+used[i-1].quantity)fail('La copia asigna las mismas unidades a dos ventas.');}
 for(const e of b.expenses)if(!uid(e.id)||!integer(e.amount,1)||!validDate(e.date)||!text(e.title,120)||!e.title.trim()||!text(e.notes)||typeof e.voided!=='boolean')fail('Hay un gasto no válido.');
 validateInventoryExtensions(b);
 return {learning:validateLearning(raw.learning),goals:raw.goals,business:{...b,profitAllocation:validateProfitAllocation(b.profitAllocation===undefined?defaultProfitAllocation():b.profitAllocation)}};
}

function goalValue(g){if(g.mode==='checklist')return {current:g.steps.filter(s=>s.done).length,target:g.steps.length||1};if(g.mode==='business')return {current:Math.max(0,salesStats().netProfit),target:g.target};return {current:g.current,target:g.target};}
function syncGoals(){if(!state?.goals||!state.business)return;for(const g of state.goals){const v=goalValue(g),done=v.current>=v.target;if(done&&!g.completedAt)g.completedAt=today();if(!done)g.completedAt=null;}}
function goalProgressText(g){const v=goalValue(g);if(g.mode==='business')return `${money(v.current)} de ${money(v.target)}`;return `${v.current.toLocaleString('es')} de ${v.target.toLocaleString('es')} ${esc(g.mode==='checklist'?'pasos':g.unit)}`;}
function deadlineText(g){if(!g.deadline)return 'Sin fecha límite';if(g.deadline===today())return 'Para hoy';return `${g.deadline<today()?'Fecha pasada · ':'Para el '}${fmtDate(g.deadline)}`;}
function renderGoals(){const active=state.goals.filter(g=>!g.archived),complete=active.filter(g=>{const v=goalValue(g);return v.current>=v.target;});const shown=state.goals.filter(g=>ui.goalFilter==='archived'?g.archived:!g.archived&&(ui.goalFilter!=='done'||complete.includes(g)));return `${heading('Dale forma a lo que quieres.','Metas personales, listas de pasos y objetivos de ganancia para tu negocio.')}<div class="analytics-top"><div class="stat"><div class="stat-top">${icon('target',16)}Metas activas</div><strong>${active.length-complete.length}</strong><small>Un paso a la vez</small></div><div class="stat"><div class="stat-top">${icon('check',16)}Metas cumplidas</div><strong>${complete.length}</strong><small>Reconoce lo que ya hiciste</small></div><div class="stat"><div class="stat-top">${icon('calendar',16)}Con fecha por llegar</div><strong>${active.filter(g=>!complete.includes(g)&&g.deadline&&g.deadline>=today()).length}</strong><small>Tus próximos compromisos</small></div></div><div class="toolbar"><div class="segmented">${[['active','Todas'],['done','Cumplidas'],['archived','Archivadas']].map(([v,n])=>`<button data-action="goal-filter" data-filter="${v}" class="${ui.goalFilter===v?'active':''}">${n}</button>`).join('')}</div><button class="btn" data-action="goal-new">${icon('plus',16)}Nueva meta</button></div><div class="goal-grid">${shown.map(g=>{const v=goalValue(g),percent=pct(v.current,v.target),done=percent>=100;return `<article class="panel goal-card"><div class="goal-top"><span class="chip ${g.category==='negocio'?'orange':''}">${esc(GOAL_CATEGORIES[g.category])}</span><button class="icon-btn" data-action="goal-edit" data-id="${g.id}" aria-label="Editar ${esc(g.title)}">${icon('edit',15)}</button></div><h2>${esc(g.title)}</h2><p class="subtle">${esc(g.notes||'Cada avance suma.')}</p><div class="goal-percent"><strong>${percent}%</strong><span>${goalProgressText(g)}</span></div><div class="progress-track"><span style="width:${Math.min(100,percent)}%"></span></div>${g.mode==='checklist'?`<div class="goal-steps">${g.steps.map(s=>`<label><input type="checkbox" data-goal="${g.id}" data-step="${s.id}" class="goal-step-check" ${s.done?'checked':''} ${g.archived?'disabled':''}><span>${esc(s.title)}</span></label>`).join('')}</div>`:''}<div class="goal-footer"><small class="${g.deadline&&g.deadline<today()&&!done?'warning-text':''}">${done?'✓ Cumplida':deadlineText(g)}</small>${g.archived?`<button class="btn soft small" data-action="goal-restore" data-id="${g.id}">Retomar</button>`:g.mode==='number'?`<button class="btn soft small" data-action="goal-progress" data-id="${g.id}">Actualizar avance</button>`:g.mode==='business'?'<small>Se actualiza con tus ventas</small>':''}</div></article>`;}).join('')||`<section class="panel empty full-span"><div class="empty-icon">${icon('target',28)}</div><strong>Algo que te gustaría conseguir.</strong>Puede ser ahorrar, aprender, terminar un proyecto o hacer crecer tu negocio.<br><button class="btn soft" data-action="goal-new">Crear mi primera meta</button></section>`}</div>`;}
function openGoal(gid){const g=state.goals.find(g=>g.id===gid);openModal(g?'Editar meta':'Una nueva dirección',`<form id="goal-form"><input name="goalId" type="hidden" value="${gid||''}">${field('title','¿Qué quieres conseguir?',g?.title||'','text','required maxlength="120" placeholder="Por ejemplo: terminar mi primer robot"')}<div class="form-row"><label class="field"><span>Área</span><select name="category">${Object.entries(GOAL_CATEGORIES).map(([v,n])=>`<option value="${v}" ${g?.category===v?'selected':''}>${n}</option>`).join('')}</select></label>${field('deadline','Fecha objetivo (opcional)',g?.deadline||'','date',`min="${FIRST}-01-01" max="${LAST}-12-31"`)}</div><label class="field"><span>¿Cómo medirás tu avance?</span><select name="mode" id="goal-mode"><option value="number" ${g?.mode==='number'?'selected':''}>Una cantidad (ahorro, libros, horas…)</option><option value="checklist" ${g?.mode==='checklist'?'selected':''}>Una lista de pasos</option><option value="business" ${g?.mode==='business'?'selected':''}>Ganancia neta de mi negocio</option></select></label><div id="goal-amount-fields" class="${g?.mode==='checklist'?'hide':''}"><div class="form-row">${field('target','Cantidad objetivo',g?.mode==='business'?amount(g.target):g?.target||100,'number','min="0.01" max="1000000000" step="0.01"')}${field('unit','Unidad',g?.unit||'%', 'text','maxlength="30" placeholder="%, libros, sesiones…"')}</div><div id="goal-current-field" class="${g?.mode==='business'?'hide':''}">${field('current','Avance actual',g?.current||0,'number','min="0" max="1000000000" step="0.01"')}</div><div id="goal-business-note" class="notice ${g?.mode==='business'?'':'hide'}">El objetivo se expresa en ${CURRENCIES[state.business.currency]}. Se actualiza con la ganancia neta acumulada; puede bajar al registrar gastos o anulaciones.</div></div><label class="field ${g?.mode==='checklist'?'':'hide'}" id="goal-steps-field"><span>Un paso por línea</span><textarea name="steps" maxlength="10000" placeholder="Armar un circuito\nLeer un sensor\nMostrar las mediciones">${esc(g?.steps.map(s=>s.title).join('\n')||'')}</textarea></label><label class="field"><span>¿Por qué es importante? (opcional)</span><textarea name="notes" maxlength="2000">${esc(g?.notes||'')}</textarea></label><div class="form-error" role="alert"></div><div class="modal-actions">${g&&!g.archived?`<button class="btn danger push" type="button" data-action="goal-archive" data-id="${g.id}">Archivar</button>`:''}<button class="btn secondary" type="button" data-action="modal-close">Cancelar</button><button class="btn" type="submit">Guardar meta</button></div></form>`);}
function saveGoal(form){try{const fd=new FormData(form),existing=state.goals.find(g=>g.id===fd.get('goalId')),mode=fd.get('mode'),title=String(fd.get('title')).trim(),lines=String(fd.get('steps')).split('\n').map(x=>x.trim()).filter(Boolean);if(!title)throw Error('Dale un nombre a tu meta.');if(mode==='checklist'&&(!lines.length||lines.length>200||lines.some(l=>l.length>160)))throw Error('Escribe entre 1 y 200 pasos, de hasta 160 caracteres cada uno.');if(new Set(lines).size!==lines.length)throw Error('Usa un nombre diferente para cada paso.');const target=mode==='checklist'?lines.length:mode==='business'?readCents(fd.get('target'),'La meta'):Number(fd.get('target')),current=mode==='number'?Number(fd.get('current')):0;if(!Number.isFinite(target)||target<=0||target>1e12||!Number.isFinite(current)||current<0||current>1e12)throw Error('Revisa la cantidad objetivo y el avance.');const steps=lines.map(title=>existing?.steps.find(s=>s.title===title)||{id:id(),title,done:false});const g={id:existing?.id||id(),title,mode,target,current,unit:mode==='business'?state.business.currency:mode==='checklist'?'pasos':String(fd.get('unit')||'').trim(),steps,category:fd.get('category'),deadline:String(fd.get('deadline')||''),notes:String(fd.get('notes')).trim(),archived:existing?.archived||false,createdAt:existing?.createdAt||today(),completedAt:existing?.completedAt||null};if(existing)Object.assign(existing,g);else state.goals.push(g);closeModal();persist();toast('Tu meta quedó guardada.');}catch(e){form.querySelector('.form-error').textContent=e.message;}}
function openGoalProgress(gid){const g=state.goals.find(g=>g.id===gid);if(!g)return;openModal('Un paso más',`<form id="goal-progress-form"><input name="goalId" type="hidden" value="${gid}"><p class="subtle">${esc(g.title)} · objetivo: ${g.target.toLocaleString('es')} ${esc(g.unit)}</p>${field('current','¿Cuánto llevas en total?',g.current,'number','required min="0" max="1000000000" step="0.01"')}<div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="modal-close">Cancelar</button><button class="btn" type="submit">Guardar avance</button></div></form>`);}

function paidSale(s){return s.payments.filter(p=>p.date<=today()).reduce((n,p)=>n+p.amount,0);}
function saleDue(s){return Math.max(0,saleTotal(s)-paidSale(s));}
function dateFilter(date){return ui.salesMonth==='all'||date.startsWith(ui.salesMonth);}
function productName(pid){return state.business.products.find(p=>p.id===pid)?.name||'Producto';}
function formActions(label,extra=''){return `<div class="form-error" role="alert"></div><div class="modal-actions">${extra}<button class="btn secondary" type="button" data-action="modal-close">Cancelar</button><button class="btn" type="submit">${label}</button></div>`;}
async function businessCommit(before,form,message){
 const app=document.querySelector('#app');app.inert=true;const controls=[...form.querySelectorAll('button,input,select,textarea')].map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);
 try{const written=await persist();if(!written){state=before;invalidateLedger();render();const error=form.querySelector('.form-error');if(error)error.textContent=storageError+' El movimiento no se guardó; los campos siguen aquí para que puedas volver a registrarlo.';return false;}closeModal();toast(message);return true;}
 finally{app.inert=false;controls.forEach(({el,disabled})=>el.disabled=disabled);}
}
async function ledgerAction(change,message){const before=clone(state),app=document.querySelector('#app');app.inert=true;try{change();const written=await persist();if(!written){state=before;invalidateLedger();render();toast('El movimiento no se guardó. '+storageError);return;}toast(message);}finally{app.inert=false;}}
function moneyField(name,label,value='',attrs=''){return field(name,`${label} (${state.business.currency})`,value,'number',`step="0.01" min="0" max="9999999999.99" ${attrs}`);}
function actualDate(fd,name='date'){const d=String(fd.get(name));if(!validDate(d)||!inRange(d)||d>today())throw Error('Usa una fecha real, entre 2026 y hoy. Los pedidos por recibir se registran en Compras.');return d;}
function inventoryCircle(stats){const r=85,c=2*Math.PI*r,f=stats.receivedCost?Math.max(0,Math.min(1,stats.inventoryCost/stats.receivedCost)):0;return `<div class="investment-ring"><svg viewBox="0 0 220 220" role="img" aria-label="Inventario por vender: ${esc(money(stats.inventoryCost))}"><circle cx="110" cy="110" r="${r}" fill="none" stroke="${stats.receivedCost?'#b9d6bd':'#edf1e8'}" stroke-width="18"/><circle cx="110" cy="110" r="${r}" fill="none" stroke="#cb925f" stroke-width="18" stroke-dasharray="${c*f} ${c}" transform="rotate(-90 110 110)" stroke-linecap="${f?'round':'butt'}"/></svg><div class="ring-center"><small>POR VENDER</small><strong>${money(stats.inventoryCost)}</strong><span>${stats.inventoryQuantity} unidades</span></div></div>`;}
function renderBusiness(){const b=state.business,stats=salesStats(),tabs=[['overview','Resumen'],['products','Productos'],['sales','Ventas y cobros'],['purchases','Compras / pedidos'],['expenses','Gastos'],['allocation','Repartir ganancias']];return `${heading('Tu negocio, con las cuentas claras.','De tus compras en Temu a tus primeras ganancias. Cada movimiento cuenta.')}<div class="business-toolbar"><div class="business-tabs" role="tablist" aria-label="Apartados de ventas">${tabs.map(([v,n])=>`<button role="tab" aria-selected="${ui.businessTab===v}" data-action="business-tab" data-tab="${v}" class="${ui.businessTab===v?'active':''}">${n}</button>`).join('')}</div><button class="currency-btn" data-action="currency">${b.currency} ${icon('edit',12)}</button></div>${({overview:renderBusinessOverview,products:renderProducts,sales:renderSales,purchases:renderPurchases,expenses:renderExpenses,allocation:renderProfitAllocation}[ui.businessTab]||renderBusinessOverview)(stats)}<p class="muted-note">${icon('shield',14)}Registro manual: no se conecta ni realiza compras o ventas en Temu. Tus datos quedan en este navegador.</p>`;}
function renderBusinessOverview(s){const low=state.business.products.filter(p=>!p.deleted&&!p.archived&&stockInfo(p.id).quantity<=p.lowStock),owed=activeSales().filter(v=>saleDue(v)>0);return `<div class="business-stats">${[
 ['Ventas acumuladas',s.revenue,'Importe vendido, pagado o pendiente'],['Ganancia neta',s.netProfit,'Ventas − costo vendido − comisiones − gastos'],['Dinero cobrado',s.collected,'Pagos que ya registraste'],['Capital por recuperar',s.capitalRemaining,'Inversión y gastos que aún no cubren los cobros'],['Pendiente de cobrar',s.receivable,'Saldos de tus clientes'],['Saldo de caja',s.cashBalance,'Cobros − compras pagadas − comisiones − gastos']
 ].map(([title,v,note])=>`<div class="stat"><div class="stat-top">${title}</div><strong class="${v<0?'negative':''}">${money(v)}</strong><small>${note}</small></div>`).join('')}</div><div class="business-overview-grid"><section class="panel investment-card"><div class="panel-head"><div><h2>Tu inversión en inventario</h2><p>El círculo baja a medida que vendes unidades.</p></div>${icon('box',21)}</div>${inventoryCircle(s)}<div class="ring-legend"><span><i style="background:#cb925f"></i>Por vender</span><span><i style="background:#b9d6bd"></i>Ya vendido, a costo</span></div><div class="inventory-progress-note">${s.soldUnits} de ${s.receivedUnits} unidades recibidas vendidas · ${s.pendingUnits} en camino<br><strong>Total invertido en compras: ${money(s.invested)}</strong></div><p class="accounting-note">El círculo muestra el <strong>costo</strong> del inventario restante, no la ganancia. Los cobros y la recuperación del capital se calculan aparte.</p></section><section class="panel chart-panel"><div class="chart-header"><div><h2>Ventas y ganancia por mes</h2><p class="subtle" style="font-size:11px;margin-top:5px">Últimos seis meses · ${state.business.currency}</p></div><button class="text-btn" data-action="sales-csv">${icon('download',14)}CSV</button></div>${businessChart()}<div class="legend"><span><i class="dot" style="background:#75a68c"></i>Ventas</span><span><i class="dot" style="background:#cb925f"></i>Ganancia neta</span></div><p class="accounting-note">La ganancia puede incluir ventas aún por cobrar. El saldo de caja solo usa pagos registrados; comprar inventario no es una pérdida por sí mismo.</p></section></div><div class="grid-2 section-gap"><section class="panel"><div class="panel-head"><div><h2>Lo que falta cobrar</h2><p>${owed.length} ventas con saldo pendiente</p></div></div><div class="panel-body">${owed.slice(0,5).map(v=>`<div class="ledger-row"><div><strong>${esc(v.customer||productName(v.productId))}</strong><small>${esc(productName(v.productId))} · ${fmtDate(v.date)}</small></div><b>${money(saleDue(v))}</b><button class="btn soft small" data-action="sale-payment" data-id="${v.id}">Cobrar</button></div>`).join('')||'<div class="empty">No hay saldos pendientes de clientes.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Existencias por revisar</h2><p>Umbrales que tú eliges para cada producto</p></div><button class="text-btn" data-action="business-tab" data-tab="products">Ver productos</button></div><div class="panel-body">${low.slice(0,5).map(p=>{const st=stockInfo(p.id);return `<div class="ledger-row"><div><strong>${esc(p.name)}</strong><small>${st.quantity?'Pocas unidades':'Sin existencias'}${st.pending?' · '+st.pending+' en camino':''}</small></div><span class="chip orange">${st.quantity} disponibles</span><button class="icon-btn" data-action="purchase-new" data-id="${p.id}" aria-label="Añadir compra de ${esc(p.name)}">${icon('plus',15)}</button></div>`;}).join('')||'<div class="empty">Aquí aparecerán tus alertas de existencias.</div>'}</div></section></div>${!state.business.products.some(p=>!p.deleted)?`<div class="start-business"><div>${icon('shop',32)}<h2>Tu primer producto, bien registrado.</h2><p>Añade su cantidad, costo y precio de venta. El resto se calcula con tus movimientos.</p></div><button class="btn" data-action="product-new">${icon('plus',16)}Añadir mi primer producto</button></div>`:''}`;}
function businessChart(){const now=dateObj(today()),months=Array.from({length:6},(_,i)=>key(new Date(now.getFullYear(),now.getMonth()-5+i,1,12)).slice(0,7));const vals=months.map(m=>{const sales=activeSales().filter(s=>s.date.startsWith(m)),revenue=sales.reduce((n,s)=>n+saleTotal(s),0),profit=revenue-sales.reduce((n,s)=>n+saleCOGS(s)+s.fees,0)-state.business.expenses.filter(e=>!e.voided&&e.date.startsWith(m)&&e.date<=today()).reduce((n,e)=>n+e.amount,0);return {m,revenue,profit};});const abs=Math.max(100,...vals.flatMap(v=>[v.revenue,Math.abs(v.profit)])),hasNegative=vals.some(v=>v.profit<0),top=32,zero=hasNegative?179:229,span=hasNegative?132:182,w=640;return `<svg class="chart business-chart" viewBox="0 0 ${w} 280" role="img" aria-label="Ventas y ganancias de los últimos seis meses"><line x1="30" y1="${zero}" x2="630" y2="${zero}" stroke="#ccd8c6"/>${vals.map((v,i)=>{const x=65+i*98;return `<g><title>${v.m}: ventas ${money(v.revenue)}, ganancia ${money(v.profit)}</title>${[['revenue',x-15,'#75a68c'],['profit',x+15,'#cb925f']].map(([k,xx,color])=>{const value=v[k],height=Math.abs(value)/abs*(value<0?48:span);return `<rect x="${xx}" y="${value>=0?zero-height:zero}" width="23" height="${Math.max(height,1)}" rx="4" fill="${color}"/>`;}).join('')}<text x="${x+10}" y="265" text-anchor="middle">${MONTH[Number(v.m.slice(5))-1].slice(0,3)}</text></g>`;}).join('')}<text x="32" y="${top-10}">${esc(money(abs))}</text>${hasNegative?'<text x="30" y="238">Valores bajo la línea = pérdidas</text>':''}</svg>`;}
function ledgerFilter(){return `<div class="ledger-filter"><label><span>Ver</span><select id="sales-period"><option value="all" ${ui.salesMonth==='all'?'selected':''}>Todo el historial</option><option value="month" ${ui.salesMonth!=='all'?'selected':''}>Un mes</option></select></label>${ui.salesMonth!=='all'?`<input type="month" id="sales-month" aria-label="Mes del historial" value="${ui.salesMonth}" min="2026-01" max="2051-12">`:''}</div>`;}
function renderProducts(){const ps=state.business.products.filter(p=>(ui.productTrash?!!p.deleted:!p.deleted&&(ui.showArchivedProducts||!p.archived))&&p.name.toLowerCase().includes(ui.productSearch.toLowerCase())),trashed=state.business.products.filter(p=>p.deleted).length;return `<div class="toolbar"><div class="search-box">${icon('box',17)}<input id="product-search" value="${esc(ui.productSearch)}" placeholder="Buscar producto…" aria-label="Buscar producto"></div><div class="product-filter-row"><button class="btn secondary small" data-action="product-archived">${ui.showArchivedProducts?'Ocultar archivados':'Ver archivados'}</button><button class="btn secondary small" data-action="product-trash-view">${icon('trash',14)}${ui.productTrash?'Volver a productos':`Papelera (${trashed})`}</button><button class="btn" data-action="product-new">${icon('plus',16)}Nuevo producto</button></div></div><p class="product-edit-help">${ui.productTrash?'Los productos en la papelera conservan sus movimientos. Puedes recuperarlos cuando quieras.':'Usa el lápiz para editar el producto y el costo de cada lote de compra. La papelera retira productos sin unidades ni pedidos pendientes y permite recuperarlos.'}</p><div class="panel table-scroll"><table class="data-table"><thead><tr><th>Producto</th><th>Disponibles</th><th>Costo unitario*</th><th>Precio de venta</th><th>Inversión total</th><th>Acciones</th></tr></thead><tbody>${ps.map(p=>{const st=stockInfo(p.id),orders=state.business.purchases.filter(o=>o.productId===p.id&&!o.voided&&o.date<=today()),units=orders.reduce((n,o)=>n+o.quantity,0),historic=units?Math.round(orders.reduce((n,o)=>n+purchaseTotal(o),0)/units):0;return `<tr data-product="${p.id}" class="${p.archived?'muted-row':''}"><td><strong>${esc(p.name)}</strong><small class="${p.deleted?'trash-label':''}">${p.deleted?'En papelera':p.archived?'Archivado':st.pending?st.pending+' en camino':esc(p.notes||'Temu / reventa')}</small></td><td><span class="stock-number ${st.quantity<=p.lowStock?'warning-text':''}">${st.quantity}</span></td><td>${money(st.quantity?st.averageCost:historic)}</td><td>${money(p.price)}</td><td>${money(st.invested)}</td><td><div class="action-row">${p.deleted?`<button class="btn soft small" data-action="product-restore" data-id="${p.id}">Recuperar producto</button>`:`<button class="btn soft small" data-action="sale-new" data-id="${p.id}" ${!st.quantity||p.archived?'disabled':''}>Vender</button><button class="icon-btn" data-action="purchase-new" data-id="${p.id}" aria-label="Añadir compra de ${esc(p.name)}">${icon('plus',15)}</button><button class="icon-btn" data-action="product-edit" data-id="${p.id}" aria-label="Editar ${esc(p.name)}">${icon('edit',14)}</button><button class="icon-btn trash-btn" data-action="product-trash" data-id="${p.id}" aria-label="Eliminar ${esc(p.name)}" title="Enviar a la papelera">${icon('trash',15)}</button>`}</div></td></tr>`;}).join('')||`<tr><td colspan="6"><div class="empty"><strong>${ui.productTrash?'La papelera está vacía.':'Aún no hay productos aquí.'}</strong>${ui.productTrash?'Los productos que retires aparecerán aquí.':'Empieza con el nombre, la cantidad comprada y el precio.'}</div></td></tr>`}</tbody></table></div><p class="muted-note">* Costo promedio con el envío asignado de las unidades disponibles. Sin existencias, se muestra el promedio de las compras vigentes, incluidos los pedidos en camino. Una corrección del costo de compra actualiza también el costo de las ventas que usaron ese lote.</p>`;}

function renderSales(){const sales=[...state.business.sales].filter(s=>dateFilter(s.date)).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="toolbar">${ledgerFilter()}<div class="action-row"><button class="btn secondary small" data-action="sales-csv">${icon('download',15)}Exportar CSV</button><button class="btn" data-action="sale-new">${icon('plus',15)}Registrar venta</button></div></div><div class="panel table-scroll"><table class="data-table"><thead><tr><th>Fecha / cliente</th><th>Producto</th><th>Cantidad</th><th>Venta</th><th>Costo vendido</th><th>Resultado*</th><th>Por cobrar</th><th>Acciones</th></tr></thead><tbody>${sales.map(s=>{const gain=saleTotal(s)-saleCOGS(s)-s.fees;return `<tr class="${s.voided?'muted-row':''}"><td>${fmtDate(s.date)}<small>${esc(s.customer||'Sin cliente indicado')}</small></td><td><strong>${esc(productName(s.productId))}</strong><small>${s.voided?'Anulada':paidSale(s)>=saleTotal(s)?'Pagada':'Cobro pendiente'}</small></td><td>${s.quantity}</td><td>${money(saleTotal(s))}</td><td>${money(saleCOGS(s))}</td><td class="${gain<0?'negative':''}">${money(gain)}</td><td>${s.voided?'—':money(saleDue(s))}</td><td><div class="action-row">${!s.voided&&saleDue(s)>0?`<button class="btn soft small" data-action="sale-payment" data-id="${s.id}">Cobrar</button>`:''}<button class="icon-btn" data-action="sale-detail" data-id="${s.id}" aria-label="Ver venta">${icon('more',17)}</button></div></td></tr>`;}).join('')||'<tr><td colspan="8"><div class="empty">No hay ventas en este periodo. Al registrar una, las existencias bajan automáticamente.</div></td></tr>'}</tbody></table></div><p class="muted-note">* Venta − costo de las unidades − gastos de esa venta. Los gastos generales se descuentan de la ganancia neta del resumen.</p>`;}
function renderPurchases(){const ps=[...state.business.purchases].filter(p=>dateFilter(p.date)).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="toolbar">${ledgerFilter()}<button class="btn" data-action="purchase-new">${icon('plus',15)}Registrar compra</button></div><div class="banner">${icon('box',18)}Los pedidos en camino cuentan como inversión pagada, pero no como existencias disponibles hasta que los marques recibidos.</div><div class="panel table-scroll"><table class="data-table"><thead><tr><th>Fecha</th><th>Producto</th><th>Cantidad</th><th>Costo unitario</th><th>Envío / extras</th><th>Total invertido</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${ps.map(p=>`<tr class="${p.voided?'muted-row':''}"><td>${fmtDate(p.date)}</td><td><strong>${esc(productName(p.productId))}</strong><small>${esc(p.notes||'')}${p.expectedDate?' · Llega: '+fmtDate(p.expectedDate):''}</small></td><td>${p.quantity}</td><td>${money(p.unitCost)}</td><td>${money(p.extraCost)}</td><td>${money(purchaseTotal(p))}</td><td><span class="chip ${p.status==='pending'?'orange':''}">${p.voided?'Anulada':p.status==='received'?'Recibida':'En camino'}</span></td><td><div class="action-row">${!p.voided&&p.status==='pending'?`<button class="btn soft small" data-action="purchase-receive" data-id="${p.id}">Recibir</button>`:''}${!p.voided?`<button class="icon-btn" data-action="purchase-edit" data-id="${p.id}" aria-label="Corregir costo de ${esc(productName(p.productId))}">${icon('edit',14)}</button>`:''}${!p.voided&&!batchUsed(p.id).length?`<button class="text-btn" data-action="purchase-void" data-id="${p.id}">Anular</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">Aquí tendrás tus compras y pedidos de Temu.</div></td></tr>'}</tbody></table></div>`;}
function renderExpenses(){const es=[...state.business.expenses].filter(e=>dateFilter(e.date)).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="toolbar">${ledgerFilter()}<button class="btn" data-action="expense-new">${icon('plus',15)}Registrar gasto</button></div><div class="banner">${icon('money',18)}Registra gastos generales como publicidad o empaque. No repitas el envío o las comisiones que ya incluiste en una compra o venta.</div><div class="panel table-scroll"><table class="data-table"><thead><tr><th>Fecha</th><th>Concepto</th><th>Importe</th><th>Nota</th><th>Acciones</th></tr></thead><tbody>${es.map(e=>`<tr class="${e.voided?'muted-row':''}"><td>${fmtDate(e.date)}</td><td><strong>${esc(e.title)}</strong>${e.voided?'<small>Anulado</small>':''}</td><td>${money(e.amount)}</td><td>${esc(e.notes)}</td><td>${!e.voided?`<button class="text-btn" data-action="expense-void" data-id="${e.id}">Anular</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Sin gastos registrados en este periodo.</div></td></tr>'}</tbody></table></div>`;}

function productOptions(selected,onlyStock=false){return state.business.products.filter(p=>!p.deleted&&(!p.archived||p.id===selected)&&(!onlyStock||stockInfo(p.id).quantity>0)).map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}${onlyStock?' · '+stockInfo(p.id).quantity+' disponibles':''}</option>`).join('');}
function openPurchase(pid){if(!state.business.products.some(p=>!p.deleted)){openProduct(null);return;}openModal('Registrar una compra o pedido',`<form id="purchase-form"><label class="field"><span>Producto</span><select name="productId" required>${productOptions(pid)}</select></label><div class="form-row">${field('quantity','Unidades compradas',1,'number','required min="1" max="1000000" step="1"')}${moneyField('unitCost','Costo de cada unidad','','required')}</div><div class="form-row">${moneyField('extraCost','Envío / impuestos de este lote',0)}${field('date','Fecha de compra',today(),'date',`required min="2026-01-01" max="${today()}"`)}</div><label class="field"><span>Estado</span><select name="status"><option value="received">Ya recibido</option><option value="pending">Pedido en camino</option></select></label>${field('expectedDate','Llegada prevista (opcional)','','date','min="2026-01-01" max="2051-12-31"')}<label class="field"><span>Referencia o nota</span><textarea name="notes" maxlength="1000" placeholder="Número de pedido, lote o detalle de Temu…"></textarea></label><div class="notice">Se registra el importe total como inversión pagada. Las unidades en camino no se pueden vender hasta que marques el pedido recibido.</div>${formActions('Guardar compra')}</form>`);}
async function savePurchase(form){const before=clone(state);try{const fd=new FormData(form),productId=fd.get('productId');if(!state.business.products.some(p=>p.id===productId&&!p.deleted))throw Error('Elige un producto.');const date=actualDate(fd),status=fd.get('status'),p={id:id(),productId,quantity:readQuantity(fd.get('quantity')),unitCost:readCents(fd.get('unitCost'),'El costo unitario'),extraCost:readCents(fd.get('extraCost')||0,'El envío'),date,status,receivedDate:status==='received'?date:'',expectedDate:String(fd.get('expectedDate')||''),notes:String(fd.get('notes')).trim(),voided:false};if(!Number.isSafeInteger(purchaseTotal(p))||purchaseTotal(p)>1e12)throw Error('La inversión total es demasiado grande.');if(p.expectedDate&&p.expectedDate<date)throw Error('La llegada prevista no puede ser anterior a la compra.');state.business.purchases.push(p);await businessCommit(before,form,status==='received'?'Compra guardada. Existencias actualizadas.':'Pedido guardado como inversión en camino.');}catch(e){form.querySelector('.form-error').textContent=e.message;}}
function openReceive(pid){const p=state.business.purchases.find(p=>p.id===pid);if(!p||p.status!=='pending'||p.voided)return;openModal('Recibir mi pedido',`<form id="receive-form"><input type="hidden" name="purchaseId" value="${pid}"><p>${esc(productName(p.productId))} · ${p.quantity} unidades</p>${field('date','¿Cuándo lo recibiste?',today(),'date',`required min="${p.date}" max="${today()}"`)}<p class="notice">Las unidades pasarán a estar disponibles. No se vuelve a sumar la inversión: ya estaba registrada al comprar.</p>${formActions('Marcar recibido')}</form>`);}
function openSale(pid){const options=productOptions(pid,true);if(!options){openModal('Primero, tus existencias',`<div class="empty"><div class="empty-icon">${icon('box',28)}</div><strong>No hay unidades recibidas para vender.</strong>Añade una compra o marca recibido un pedido en camino.<br><button class="btn" data-action="business-go-purchases">Ver compras y pedidos</button></div>`);return;}const first=state.business.products.find(p=>p.id===pid&&!p.deleted&&!p.archived&&stockInfo(p.id).quantity>0)||state.business.products.find(p=>!p.deleted&&!p.archived&&stockInfo(p.id).quantity>0);openModal('Registrar una venta',`<form id="sale-form"><label class="field"><span>Producto</span><select name="productId" id="sale-product" required>${productOptions(first.id,true)}</select></label><div class="form-row">${field('quantity','Unidades vendidas',1,'number',`required min="1" max="${stockInfo(first.id).quantity}" step="1"`)}${moneyField('unitPrice','Precio por unidad',amount(first.price),'required')}</div><div class="form-row">${moneyField('discount','Descuento total',0)}${moneyField('fees','Comisiones / entrega de esta venta',0)}</div><div class="form-row">${field('date','Fecha de venta',today(),'date',`required min="2026-01-01" max="${today()}"`)}${moneyField('paid','Cobrado ahora','','placeholder="Vacío = ya pagado todo"')}</div>${field('customer','Cliente o referencia', '', 'text','maxlength="120" placeholder="Necesario si queda dinero por cobrar"')}<label class="field"><span>Nota (opcional)</span><textarea name="notes" maxlength="1000"></textarea></label><div id="sale-estimate" class="sale-estimate"></div><p class="muted-note">Los costos incluyen el envío de compra. Las unidades se toman de los lotes recibidos más antiguos disponibles.</p>${formActions('Guardar venta')}</form>`);updateSaleEstimate();}
function saleDraft(form){const fd=new FormData(form),productId=fd.get('productId'),product=state.business.products.find(p=>p.id===productId&&!p.deleted&&!p.archived);if(!product)throw Error('Elige un producto activo para vender.');const quantity=readQuantity(fd.get('quantity')),unitPrice=readCents(fd.get('unitPrice'),'El precio'),discount=readCents(fd.get('discount')||0,'El descuento'),fees=readCents(fd.get('fees')||0,'Los gastos de venta'),date=actualDate(fd),total=quantity*unitPrice-discount;if(!Number.isSafeInteger(total)||total<0||total>1e12)throw Error('El descuento no puede superar el precio total. Revisa los importes.');const paid=String(fd.get('paid')).trim()===''?total:readCents(fd.get('paid'),'Lo cobrado');if(paid>total)throw Error('Lo cobrado no puede superar el total de la venta.');const customer=String(fd.get('customer')).trim(),allocations=allocateSale(productId,quantity,date);return {productId,quantity,unitPrice,discount,fees,date,paid,total,customer,allocations,notes:String(fd.get('notes')).trim()};}
function updateSaleEstimate(){const form=document.querySelector('#sale-form');if(!form)return;const box=form.querySelector('#sale-estimate');try{const d=saleDraft(form),cost=d.allocations.reduce((n,a)=>n+a.cost,0);box.innerHTML=`<div><span>Total de venta</span><strong>${money(d.total)}</strong></div><div><span>Costo de estas unidades</span><strong>${money(cost)}</strong></div><div><span>Resultado antes de gastos generales</span><strong class="${d.total-cost-d.fees<0?'negative':''}">${money(d.total-cost-d.fees)}</strong></div><div><span>Quedará por cobrar</span><strong>${money(d.total-d.paid)}</strong></div>`;}catch(e){box.textContent=e.message;}}
async function saveSale(form){const before=clone(state);try{const d=saleDraft(form);if(d.paid<d.total&&!d.customer)throw Error('Indica el cliente o una referencia para poder identificar el saldo pendiente.');state.business.sales.push({id:id(),productId:d.productId,quantity:d.quantity,unitPrice:d.unitPrice,discount:d.discount,fees:d.fees,date:d.date,customer:d.customer,notes:d.notes,allocations:d.allocations,payments:d.paid?[{id:id(),date:d.date,amount:d.paid}]:[],voided:false});await businessCommit(before,form,'Venta guardada. Inventario, inversión y ganancias actualizados.');}catch(e){form.querySelector('.form-error').textContent=e.message;}}
function openPayment(sid){const s=state.business.sales.find(s=>s.id===sid);if(!s||s.voided||!saleDue(s))return;openModal('Registrar un cobro',`<form id="payment-form"><input type="hidden" name="saleId" value="${sid}"><p><strong>${esc(s.customer||productName(s.productId))}</strong></p><p class="subtle">Pendiente: ${money(saleDue(s))}</p><div class="form-row">${moneyField('amount','Dinero recibido',amount(saleDue(s)),`required min="0.01" max="${amount(saleDue(s))}"`)}${field('date','Fecha de cobro',today(),'date',`required min="${s.date}" max="${today()}"`)}</div><p class="notice">Este cobro no vuelve a descontar inventario ni suma otra venta: solo reduce el saldo pendiente y actualiza la caja.</p>${formActions('Guardar cobro')}</form>`);}
function openSaleDetail(sid){const s=state.business.sales.find(s=>s.id===sid);if(!s)return;openModal('Detalle de la venta',`<h3>${esc(productName(s.productId))}</h3><p class="subtle">${fmtDate(s.date,true)} · ${s.quantity} unidades · ${esc(s.customer||'Sin cliente indicado')}</p><div class="sale-estimate"><div><span>Precio por unidad</span><strong>${money(s.unitPrice)}</strong></div><div><span>Descuento total</span><strong>${money(s.discount)}</strong></div><div><span>Venta total</span><strong>${money(saleTotal(s))}</strong></div><div><span>Costo de unidades vendidas</span><strong>${money(saleCOGS(s))}</strong></div><div><span>Comisiones / entrega</span><strong>${money(s.fees)}</strong></div><div><span>Resultado antes de gastos generales</span><strong>${money(saleTotal(s)-saleCOGS(s)-s.fees)}</strong></div></div><h3 style="margin-top:20px">Cobros registrados</h3>${s.payments.map(p=>`<div class="ledger-row"><span>${fmtDate(p.date)}</span><b>${money(p.amount)}</b></div>`).join('')||'<p class="muted-note">No se ha registrado ningún cobro.</p>'}<p class="muted-note">${esc(s.notes)}</p>${s.voided?'<div class="notice">Venta anulada. Sus unidades se devolvieron al inventario y sus importes ya no cuentan en el resumen.</div>':`<div class="modal-actions"><button class="btn danger push" data-action="sale-void" data-id="${sid}">Anular y devolver unidades</button>${saleDue(s)?`<button class="btn" data-action="sale-payment" data-id="${sid}">Registrar cobro</button>`:''}</div>`}`);}
function openExpense(){openModal('Un gasto de tu negocio',`<form id="expense-form">${field('title','Concepto','','text','required maxlength="120" placeholder="Por ejemplo: empaque o publicidad"')}<div class="form-row">${moneyField('amount','Importe','','required min="0.01"')}${field('date','Fecha',today(),'date',`required min="2026-01-01" max="${today()}"`)}</div><label class="field"><span>Nota (opcional)</span><textarea name="notes" maxlength="1000" placeholder="No repitas un gasto ya incluido en una compra o venta."></textarea></label>${formActions('Guardar gasto')}</form>`);}
function exportSalesCSV(){const cell=v=>{let s=String(v??'');if(typeof v==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Fecha','Producto','Cliente','Cantidad','Precio unitario','Descuento total','Venta total','Costo vendido','Comisiones','Resultado antes de gastos generales','Cobrado','Por cobrar','Estado','Moneda']];for(const s of state.business.sales.filter(s=>dateFilter(s.date))){rows.push([s.date,productName(s.productId),s.customer,s.quantity,amount(s.unitPrice),amount(s.discount),amount(saleTotal(s)),amount(saleCOGS(s)),amount(s.fees),amount(saleTotal(s)-saleCOGS(s)-s.fees),amount(paidSale(s)),amount(saleDue(s)),s.voided?'Anulada':'Vigente',state.business.currency]);}const csv='\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`rumbo-ventas-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('CSV de ventas preparado.');}

document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id:entityId}=el.dataset;
 try{switch(action){
 case 'more-nav':openModal('Más de tu espacio',`<div class="more-grid">${[['progress','chart','Mi progreso'],['routes','route','Mi ruta de aprendizaje'],['settings','settings','Ajustes y copias']].map(([v,i,n])=>`<button data-action="view" data-view="${v}">${icon(i,24)}${n}</button>`).join('')}</div>`);break;
 case 'habit-go-today':ui.date=today();render();break;
 case 'goal-filter':ui.goalFilter=el.dataset.filter;render();break;
 case 'goal-new':openGoal(null);break;
 case 'goal-edit':openGoal(entityId);break;
 case 'goal-progress':openGoalProgress(entityId);break;
 case 'goal-archive':{const g=state.goals.find(g=>g.id===entityId);if(g){g.archived=true;closeModal();persist();toast('Meta archivada. Puedes retomarla después.');}break;}
 case 'goal-restore':{const g=state.goals.find(g=>g.id===entityId);if(g){g.archived=false;persist();}break;}
 case 'business-tab':ui.businessTab=el.dataset.tab;render();break;
 case 'business-go-purchases':ui.salesMonth='all';closeModal();ui.businessTab='purchases';ui.view='business';render();break;
 case 'product-new':openProduct(null);break;
 case 'product-edit':openProduct(entityId);break;
 case 'product-archived':ui.productTrash=false;ui.showArchivedProducts=!ui.showArchivedProducts;render();break;
 case 'product-archive':{const p=state.business.products.find(p=>p.id===entityId&&!p.deleted);if(p){const archived=!p.archived;closeModal();await ledgerAction(()=>{state.business.products.find(p=>p.id===entityId).archived=archived;},archived?'Producto archivado. Sus movimientos y existencias se conservan.':'Producto retomado.');}break;}
 case 'purchase-new':openPurchase(entityId);break;
 case 'purchase-receive':openReceive(entityId);break;
 case 'purchase-void':{const p=state.business.purchases.find(p=>p.id===entityId);if(!p||p.voided||batchUsed(p.id).length)return;confirmation('¿Anular esta compra con reembolso?',`Se retirarán ${p.quantity} unidades y ${money(purchaseTotal(p))} de la inversión. Hazlo solo si no hay unidades vendidas de este lote y recuperaste el importe de la compra. Si hay gastos sin reembolso, regístralos en Gastos.`,()=>ledgerAction(()=>{p.voided=true;},'Compra anulada; movimiento conservado en el historial.'),'Anular compra');break;}
 case 'sale-new':openSale(entityId);break;
 case 'sale-detail':openSaleDetail(entityId);break;
 case 'sale-payment':openPayment(entityId);break;
 case 'sale-void':{const s=state.business.sales.find(s=>s.id===entityId);if(!s||s.voided)return;confirmation('¿Anular la venta y devolver las unidades?',`Se restaurarán ${s.quantity} unidades al inventario y se retirarán la venta, los cobros y sus comisiones del resumen. Confirma solo si recibiste los productos y devolviste lo cobrado. Si quedaron gastos sin reembolso, regístralos en Gastos.`,()=>ledgerAction(()=>{s.voided=true;const product=state.business.products.find(p=>p.id===s.productId);if(product?.deleted){product.deleted=false;product.deletedAt=null;product.archived=false;}},'Venta anulada. Existencias y resultados actualizados.'),'Anular venta');break;}
 case 'expense-new':openExpense();break;
 case 'expense-void':{const e=state.business.expenses.find(e=>e.id===entityId);if(!e||e.voided)return;confirmation('¿Anular este gasto?',`${e.title}: ${money(e.amount)}. Se conservará el movimiento como anulado y dejará de descontarse de la ganancia y la caja.`,()=>ledgerAction(()=>{e.voided=true;},'Gasto anulado.'),'Anular gasto');break;}
 case 'sales-csv':exportSalesCSV();break;
 case 'currency':openModal('Moneda de mi negocio',`<form id="currency-form"><label class="field"><span>Moneda</span><select name="currency">${Object.entries(CURRENCIES).map(([v,n])=>`<option value="${v}" ${state.business.currency===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="notice">Esta opción cambia la unidad de todos los importes. No convierte los números usando un tipo de cambio. Si ya hay movimientos, úsala solo para corregir una moneda seleccionada por error.</div>${formActions('Guardar moneda')}</form>`);break;
 }}catch(e){console.error(e);toast(e.message||'No se pudo completar ese movimiento.');}
});
document.addEventListener('change',ev=>{const el=ev.target;if(el.matches('.goal-step-check')){const g=state.goals.find(g=>g.id===el.dataset.goal),s=g?.steps.find(s=>s.id===el.dataset.step);if(s){s.done=el.checked;persist();}}if(el.id==='goal-mode'){const mode=el.value;document.querySelector('#goal-amount-fields').classList.toggle('hide',mode==='checklist');document.querySelector('#goal-steps-field').classList.toggle('hide',mode!=='checklist');document.querySelector('#goal-current-field').classList.toggle('hide',mode==='business');document.querySelector('#goal-business-note').classList.toggle('hide',mode!=='business');const unit=el.form.elements.unit;unit.disabled=mode==='business';}if(el.id==='sale-product'){const p=state.business.products.find(p=>p.id===el.value),form=el.form;if(p){form.elements.unitPrice.value=amount(p.price);form.elements.quantity.max=stockInfo(p.id).quantity;}updateSaleEstimate();}if(el.id==='sales-period'){ui.salesMonth=el.value==='all'?'all':today().slice(0,7);render();}if(el.id==='sales-month'&&/^\d{4}-\d\d$/.test(el.value)){ui.salesMonth=el.value;render();}if(el.closest('#sale-form'))updateSaleEstimate();});
document.addEventListener('input',ev=>{if(ev.target.closest('#sale-form'))updateSaleEstimate();if(ev.target.id==='product-search'){const input=ev.target,pos=input.selectionStart;ui.productSearch=input.value;render();const next=document.querySelector('#product-search');next.focus();next.setSelectionRange(pos,pos);}});
document.addEventListener('submit',async ev=>{const form=ev.target,name=form.getAttribute('id');if(!['goal-form','goal-progress-form','product-form','purchase-form','receive-form','sale-form','payment-form','expense-form','currency-form'].includes(name))return;ev.preventDefault();try{
 if(name==='goal-form')return saveGoal(form);if(name==='product-form')return saveProduct(form);if(name==='purchase-form')return savePurchase(form);if(name==='sale-form')return saveSale(form);
 const fd=new FormData(form),before=clone(state);
 if(name==='goal-progress-form'){const g=state.goals.find(g=>g.id===fd.get('goalId')),value=Number(fd.get('current'));if(!g||!Number.isFinite(value)||value<0||value>1e12)throw Error('Revisa el avance.');g.current=value;}
 if(name==='receive-form'){const p=state.business.purchases.find(p=>p.id===fd.get('purchaseId')),date=actualDate(fd);if(!p||p.voided||p.status!=='pending')throw Error('El pedido ya no está pendiente.');if(date<p.date)throw Error('La recepción no puede ser anterior a la compra.');p.status='received';p.receivedDate=date;}
 if(name==='payment-form'){const s=state.business.sales.find(s=>s.id===fd.get('saleId')),value=readCents(fd.get('amount')),date=actualDate(fd);if(!s||s.voided||date<s.date||value<=0||value>saleDue(s))throw Error('El cobro debe ser mayor que cero y no superar el saldo pendiente.');s.payments.push({id:id(),date,amount:value});}
 if(name==='expense-form'){const title=String(fd.get('title')).trim(),value=readCents(fd.get('amount')),date=actualDate(fd);if(!title||value<=0)throw Error('Indica el concepto y un importe mayor que cero.');state.business.expenses.push({id:id(),title,amount:value,date,notes:String(fd.get('notes')).trim(),voided:false});}
 if(name==='currency-form'){const cur=fd.get('currency');if(!CURRENCIES[cur])throw Error('Elige una moneda válida.');state.business.currency=cur;}
 await businessCommit(before,form,'Cambio guardado.');
 }catch(e){const error=form.querySelector('.form-error');if(error)error.textContent=e.message;else toast(e.message);}});

(async()=>{await initStorage();syncGoals();render();})();
